// HasCheckResultsWith applies the HasEdge predicate on the "check_results" edge with a given conditions (other predicates).
func HasCheckResultsWith(preds ...predicate.CheckResult) predicate.Challenge {
	return predicate.Challenge(func(s *sql.Selector) {
		step := newCheckResultsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasWriteups applies the HasEdge predicate on the "writeups" edge.
func HasWriteups() predicate.Challenge {
	return predicate.Challenge(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, WriteupsTable, WriteupsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWriteupsWith applies the HasEdge predicate on the "writeups" edge with a given conditions (other predicates).
func HasWriteupsWith(preds ...predicate.Writeup) predicate.Challenge {
	return predicate.Challenge(func(s *sql.Selector) {
		step := newWriteupsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Challenge) predicate.Challenge {
	return predicate.Challenge(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Challenge) predicate.Challenge {
	return predicate.Challenge(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Challenge) predicate.Challenge {
	return predicate.Challenge(sql.NotPredicates(p))
}
